# Define the tangent to the hyperbola at P
tangent_at_P = (b / sp.sqrt(a**2 - b**2), 0)

# Calculate the area of the triangle formed by the tangent, the normal, and the x-axis
area_triangle = sp.Rational(1, 2) * sp.Abs(normal_at_P * tangent_at_P)

